/** The words a day can pick, in alphabetical order. */
export const WORDLE_ANSWERS: readonly string[] = ANSWER_LINES.join(" ").split(" ");

let guessSet: Set<string> | null = null;

/** Whether a lowercase five-letter string is an accepted guess. */
export function isWordleWord(word: string): boolean {
  if (!guessSet) {
    guessSet = new Set<string>();
    for (let i = 0; i < PACKED_GUESSES.length; i += 5) guessSet.add(PACKED_GUESSES.slice(i, i + 5));
  }
  return guessSet.has(word);
}
